rd-state { font-size: 11px; color: var(--qqs-sub); }\n        .qqs-card.on .qqs-card-state { color: var(--accent); font-weight: 600; }\n        .qqs-card .qqs-switch { background: #dfe3eb; }\n        .qqs-card .qqs-switch.on { background: var(--accent); }\n\n        .qqs-conn { background: var(--qqs-card); border: 1px solid var(--qqs-line); border-radius: 16px; padding: 18px; display: flex; flex-direction: column; gap: 12px; }\n        .qqs-conn-head { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; }\n        .qqs-conn-head h3 { margin: 0; font-size: 15px; }\n        .qqs-conn-head span { font-size: 12px; color: var(--qqs-sub); }\n        .qqs-form { display: grid; grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr) auto; gap: 10px; align-items: end; }\n        .qqs-field { display: flex; flex-direction: column; gap: 5px; min-width: 0; }\n        .qqs-field label { font-size: 11px; color: var(--qqs-sub); }\n        .qqs-input { width: 100%; height: 34px; padding: 0 10px; border-radius: 9px; border: 1px solid #d9dee8; background: #fbfcfe; color: var(--qqs-text); font-size: 12px; outline: none; transition: border-color .15s ease, box-shadow .15s ease; }\n        .qqs-input:focus { border-color: #6aa1ff; box-shadow: 0 0 0 3px rgba(22, 119, 255, .12); background: #fff; }\n        .qqs-btn { height: 34px; padding: 0 16px; border-radius: 9px; border: 0; background: #1677ff; color: #fff; font-size: 12px; font-weight: 600; cursor: pointer; transition: filter .15s ease; white-space: nowrap; }\n        .qqs-btn:hover { filter: brightness(1.06); }\n        .qqs-btn:disabled { opacity: .55; cursor: not-allowed; }\n        .qqs-hint { font-size: 11px; color: var(--qqs-sub); line-height: 1.7; padding-top: 2px; border-top: 1px dashed #eceff5; }\n        .qqs-settings { display: flex; align-items: center; gap: 18px; flex-wrap: wrap; font-size: 12px; color: #596074; }\n        .qqs-settings-item { display: flex; align-items: center; gap: 8px; }\n        .qqs-settings .qqs-switch { width: 38px; height: 22px; background: #dfe3eb; }\n        .qqs-settings .qqs-switch span { width: 16px; height: 16px; }\n        .qqs-settings .qqs-switch.on { background: #1677ff; }\n        .qqs-settings .qqs-switch.on span { transform: translateX(16px); }\n        @media (max-width: 720px) { .qqs-form { grid-template-columns: 1fr; } .qqs-hero-side { width: 100%; } }\n    </style>\n\n    ");
